'use strict';

import { createError, MISSING_DOC } from 'pouchdb-errors';

import { DOC_STORE, META_STORE } from './util';

import { latest as getLatest } from 'pouchdb-merge';

export default function (txn, id, opts, callback) {
  if (txn.error) {
    return callback(txn.error);
  }

  if (id.startsWith('_local/')) {
    console.log('@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@');
    console.log('@');
    console.log('@ indexeddb.get()');
    console.log('@        id:', id);
    console.log('@      opts:', opts);
    console.log('@');
    console.log('@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@');
  }

  const docStore = id.startsWith('_local/') ? META_STORE : DOC_STORE;

  txn.txn.objectStore(docStore).get(id).onsuccess = function (e) {
    var doc = e.target.result;
    var rev;

    txn.txn.commit(); // no more plans for this txn // TODO maybe can move this before result dereference

    if (!opts.rev) {
      rev = (doc && doc.rev);
    } else {
      rev = opts.latest ? getLatest(opts.rev, doc) : opts.rev;
    }

    if (!doc || (doc.deleted && !opts.rev) || !(rev in doc.revs)) {
      console.log('@ returning MISSING_DOC');
      callback(createError(MISSING_DOC, 'missing'));
      // FIXME can we just commit txn here?
      return;
    }

    var result = doc.revs[rev].data;
    result._id = doc.id;
    result._rev = rev;

    // WARNING: expecting possible old format
    console.log('@ returning doc:', result);
    console.log('@ returning metadata:', doc);
    console.log('@ callback:', callback.toString());
    callback(null, {
      doc: result,
      metadata: doc,
    });
  };
}
